// ============================================================
// 火眼载板外壳 · 参数化 OpenSCAD
// 适配：火眼载板1（105 x 140 mm）+ GD32F470V-START（60 x 95 mm）常驻插接
// 结构：下盖 + 上盖，四角螺丝；挂壁式（底边出线朝下）
// 单位：mm
// 坐标：原点 = PCB 左上角在底面的投影，X 右，Y 向下（朝出线边），Z 上
// 导出：bottom_shell() / top_shell() 分别渲染 STL
// ============================================================

/* ---------- 选件 ---------- */
part = "both"; // "bottom" | "top" | "both" | "assembly"

/* ---------- PCB ---------- */
pcb_w   = 105.0;     // 板宽 X
pcb_l   = 140.0;     // 板长 Y（y 增大 = 底边 = 出线边）
pcb_t   = 1.6;       // 板厚
pcb_clr = 0.4;       // 板周间隙

/* ---------- 外壳壁厚与间隙 ---------- */
wall      = 2.5;
floor_t   = 2.5;
lid_t     = 2.5;
fit_clr   = 0.25;    // 上下盖止口配合间隙
screw_d   = 3.2;     // M3 通孔
screw_boss_d = 8.0;  // 螺丝柱外径
screw_boss_h = 8.5;  // 与 PCB 支撑同高，兼作角撑

/* ---------- 高度链 ---------- */
pin_clr   = 8.5;     // 板下插件引脚净空
pcb_z     = pin_clr; // PCB 下表面 Z
top_of_pcb = pcb_z + pcb_t;
inside_above_pcb = 35.0; // START 板 + USB + 余量
inside_h  = pin_clr + pcb_t + inside_above_pcb;
outside_h = floor_t + inside_h + lid_t;

/* ---------- 外轮廓 ---------- */
out_w = pcb_w + 2*pcb_clr + 2*wall;
out_l = pcb_l + 2*pcb_clr + 2*wall;

// PCB 在外壳内的偏移（内腔原点）
dx = wall + pcb_clr;
dy = wall + pcb_clr;

/* ---------- 螺丝柱（相对外壳外轮廓左上角） ---------- */
screw_inset = 5.0;
screw_pos = [
  [screw_inset, screw_inset],
  [out_w - screw_inset, screw_inset],
  [screw_inset, out_l - screw_inset],
  [out_w - screw_inset, out_l - screw_inset]
];

/* ---------- 接口开孔（PCB 坐标，原点 PCB 左上角，Y 向下） ---------- */
// 底边：U7 24V 端子 / U8 负载端子 / DC1 电源座
// 端子本体约 10 x 14 mm，线从板边外侧进
term_w = 12.0;
term_h = 12.0;
term_z = pin_clr + pcb_t; // 从 PCB 面起算

u7 = [8.0, 134.2];
u8 = [22.2, 134.3];
dc1 = [61.9, 134.4];
led1 = [68.7, 135.0];
u10 = [3.2, 57.2];   // 左：串口弯针
u9  = [96.3, 86.5];  // 右：W5500
u11 = [89.8, 24.1];  // 上：报警灯座
h1  = [38.1, 37.6];  // OLED 弯针
h2  = [74.7, 81.0];  // NTC
buz = [91.7, 44.2];  // 蜂鸣器 Ø12
u5  = [13.0, 59.5];  // START 左排母
u6  = [62.0, 59.7];  // START 右排母

// START 板覆盖区（约）
start_w = 60.0;
start_l = 95.0;
start_cx = (u5[0] + u6[0]) / 2 + 0.55;
start_cy = (u5[1] + u6[1]) / 2 + 0.1;
start_x = start_cx - start_w/2;
start_y = start_cy - start_l/2;

/* ---------- 通风孔（散热 MP1584 / AMS1117 区） ---------- */
vent_cx = 85;
vent_cy = 70;

/* ============================================================ */
module rounded_box(w, l, h, r=3) {
    hull()
        for (x=[r, w-r], y=[r, l-r])
            translate([x, y]) cylinder(h=h, r=r, $fn=32);
}

module screw_boss(h) {
    difference() {
        cylinder(d=screw_boss_d, h=h, $fn=32);
        translate([0,0,-0.1]) cylinder(d=screw_d, h=h+0.2, $fn=24);
    }
}

// 上盖螺丝过孔沉头
module screw_lid_hole() {
    translate([0,0,-0.1]) {
        cylinder(d=screw_d, h=lid_t+0.2, $fn=24);
        cylinder(d=6.2, h=1.6, $fn=24); // 沉头
    }
}

/* ---------- PCB 支撑：四角立柱 + 边缘托台 ---------- */
module pcb_supports() {
    // 四角立柱（与螺丝柱一体时另建）—— 中部托台
    rail_h = pin_clr;
    rail_w = 3.0;
    // 左右托台
    for (x=[dx-0.1, dx+pcb_w-rail_w+0.1])
        translate([x, dy+5, floor_t])
            cube([rail_w, pcb_l-10, rail_h]);
    // 上下托台
    for (y=[dy-0.1, dy+pcb_l-rail_w+0.1])
        translate([dx+5, y, floor_t])
            cube([pcb_w-10, rail_w, rail_h]);
}

/* ---------- 下盖 ---------- */
module bottom_shell() {
    difference() {
        union() {
            // 外体（不含盖）
            rounded_box(out_w, out_l, floor_t + inside_h, r=3.5);
            // 螺丝柱
            for (p=screw_pos)
                translate([p[0], p[1], floor_t])
                    screw_boss(inside_h);
        }
        // 掏内腔
        translate([wall, wall, floor_t])
            rounded_box(out_w-2*wall, out_l-2*wall, inside_h+0.1, r=2.5);

        // ---- 底边开孔（Y 最大侧，外壳外表面）----
        // U7 24V 端子
        translate([dx+u7[0]-term_w/2, out_l-wall-0.1, floor_t+term_z])
            cube([term_w, wall+0.2, term_h]);
        // U8 负载端子
        translate([dx+u8[0]-term_w/2, out_l-wall-0.1, floor_t+term_z])
            cube([term_w, wall+0.2, term_h]);
        // DC1 电源座 Ø9
        translate([dx+dc1[0], out_l-wall-0.1, floor_t+term_z+2])
            rotate([-90,0,0]) cylinder(d=9.5, h=wall+0.2, $fn=32);

        // ---- 左侧开孔（X=0）：串口 ----
        translate([-0.1, dy+u10[1]-6, floor_t+term_z])
            cube([wall+0.2, 12, 10]);

        // ---- 右侧开孔（X=out_w）：W5500 / RJ45 ----
        translate([out_w-wall-0.1, dy+u9[1]-10, floor_t+term_z-1])
            cube([wall+0.2, 20, 16]);

        // ---- 底边线缆让位槽（传感器 NTC）----
        translate([dx+h2[0]-5, out_l-wall-0.1, floor_t+term_z])
            cube([10, wall+0.2, 8]);
    }

    // PCB 托台（在外壳主体之上）
    translate([0,0,floor_t]) pcb_supports();
}

/* ---------- 上盖 ---------- */
module top_shell() {
    difference() {
        union() {
            // 盖板
            rounded_box(out_w, out_l, lid_t, r=3.5);
            // 止口凸缘（插进下盖内腔）
            translate([wall+fit_clr, wall+fit_clr, lid_t])
                difference() {
                    rounded_box(out_w-2*wall-2*fit_clr, out_l-2*wall-2*fit_clr, inside_h-1, r=2.5);
                    translate([2.5, 2.5, -0.1])
                        rounded_box(out_w-2*wall-2*fit_clr-5, out_l-2*wall-2*fit_clr-5, inside_h, r=2);
                }
        }

        // 螺丝过孔
        for (p=screw_pos)
            translate([p[0], p[1], 0]) screw_lid_hole();

        // ---- START 板避让 + USB 口 ----
        // START 区域挖穿，让开发板 USB 朝上可操作（或换侧向 USB 线）
        translate([dx+start_x-1, dy+start_y-1, -0.1])
            cube([start_w+2, 32, lid_t+0.2]); // 上段（USB / GD-Link 侧）

        // ---- 蜂鸣器出声孔 ----
        translate([dx+buz[0], dy+buz[1], -0.1]) {
            cylinder(d=13, h=lid_t+0.2, $fn=32);
            // 散音孔阵列
            for (a=[0:60:300])
                rotate([0,0,a]) translate([4.5,0,0])
                    cylinder(d=2.2, h=lid_t+0.2, $fn=12);
        }

        // ---- LED1 透光孔 Ø6 ----
        translate([dx+led1[0], dy+led1[1], -0.1])
            cylinder(d=6.5, h=lid_t+0.2, $fn=24);

        // ---- OLED 视窗（模块约 27 x 27，靠 H1 弯针）----
        translate([dx+h1[0]+2, dy+h1[1]-26, -0.1])
            cube([28, 28, lid_t+0.2]);

        // ---- 上边报警灯出线/透光 ----
        translate([dx+u11[0]-8, dy+u11[1]-8, -0.1])
            cube([16, 16, lid_t+0.2]);

        // ---- 通风孔 ----
        for (i=[0:4])
            translate([dx+vent_cx-20+i*10, dy+vent_cy-15, -0.1])
                cube([3, 30, lid_t+0.2]);
    }

    // 止口内壁补强筋略
}

/* ---------- 挂壁键孔（下盖背面） ---------- */
module wall_keyholes() {
    // 靠上边（Y 小）两个葫芦孔，挂 M4 螺丝头
    for (x=[20, out_w-20])
        translate([x, 12, 0]) {
            translate([0,0,-0.1]) cylinder(d=4.5, h=floor_t+0.2, $fn=24);
            translate([0, 8, -0.1]) cylinder(d=4.5, h=floor_t+0.2, $fn=24);
            translate([-2.25, 0, -0.1]) cube([4.5, 8, floor_t+0.2]);
        }
}

/* ---------- 装配预览 ---------- */
module assembly() {
    color("SteelBlue") bottom_shell();
    color("Orange", 0.75) translate([0,0,out_l>0 ? 0 : 0]) top_shell();
    // PCB 预览
    color("DarkGreen", 0.5)
        translate([dx, dy, floor_t+pin_clr])
            cube([pcb_w, pcb_l, pcb_t]);
    // START 预览
    color("Navy", 0.4)
        translate([dx+start_x, dy+start_y, floor_t+pin_clr+pcb_t+5])
            cube([start_w, start_l, 1.6]);
}

/* ---------- 出口 ---------- */
if (part == "bottom") bottom_shell();
else if (part == "top") top_shell();
else if (part == "assembly") assembly();
else {
    // 并排导出用
    bottom_shell();
    translate([out_w + 20, 0, 0]) top_shell();
}

