  $have = (Get-Item $out).Length
  Write-Host "  -> $([math]::Round($have/1MB,2)) MB"
  if ($have -ge $expect) { Write-Host "DONE"; break }
  Start-Sleep -Seconds 2
}
$f = Get-Item $out
Write-Host "Final: $([math]::Round($f.Length/1MB,2)) MB / $([math]::Round($expect/1MB,2)) MB"

Write-Host "--- winget search ---"
try { winget search openscad --accept-source-agreements 2>&1 | Out-String } catch { Write-Host "winget fail" }
Write-Host "--- mirrors ---"
$urls = @(
