  "https://gh-proxy.com/https://github.com/openscad/openscad/releases/download/openscad-2021.01/OpenSCAD-2021.01-x86-64.zip"
)
foreach ($u in $urls) {
  try {
    $r = curl.exe -sI -L --connect-timeout 8 --max-time 12 $u 2>&1 | Out-String
    $code = ($r | Select-String "HTTP/").Line | Select-Object -Last 1
    $len = ($r | Select-String "Content-Length").Line | Select-Object -Last 1
    Write-Host "$code | $len | $u"
  } catch { Write-Host "FAIL | $u" }
}

if (Test-Path "E:\OpenSCAD-2021.01-x86-64.zip") { Remove-Item "E:\OpenSCAD-2021.01-x86-64.zip" -Force }
$dest = "E:\Program Files\OpenSCAD"
