$sw.Stop()
$f = Get-Item "E:\OpenSCAD-2021.01-x86-64.zip"
Write-Host ("Size: {0:N2} MB / 20.87 MB in {1:N1}s" -f ($f.Length/1MB), $sw.Elapsed.TotalSeconds)
if ($f.Length -ge 21884000) {
  Write-Host "Extracting..."
  if (-not (Test-Path $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
  Expand-Archive -Path "E:\OpenSCAD-2021.01-x86-64.zip" -DestinationPath $dest -Force
  Write-Host "Done. Contents:"
  Get-ChildItem $dest | Select-Object Name | Out-String
} else { Write-Host "Incomplete download" }

if (Test-Path "E:\OpenSCAD-2021.01-x86-64.zip") { $f = Get-Item "E:\OpenSCAD-2021.01-x86-64.zip"; Write-Host "Existing: $([math]::Round($f.Length/1MB,2)) MB" } else { Write-Host "No zip yet" }
Write-Host "--- test github.com ---"
curl.exe -sI -L --connect-timeout 10 --max-time 15 "https://github.com/openscad/openscad/releases/download/openscad-2021.01/OpenSCAD-2021.01-x86-64.zip" 2>&1 | Select-String "HTTP/|Content-Length|Location" | Out-String

$out = "E:\OpenSCAD-2021.01-x86-64.zip"
