if (-not (Test-Path $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
Write-Host "Extracting to $dest ..."
Expand-Archive -Path $out -DestinationPath $dest -Force
Write-Host "Done. Top level:"
Get-ChildItem $dest | Select-Object Name | Out-String
$exe = Get-ChildItem $dest -Recurse -Filter "openscad.exe" -ErrorAction SilentlyContinue | Select-Object -First 1
if ($exe) {
  Write-Host "openscad.exe: $($exe.FullName)"
  Write-Host "Test render version:"
  & $exe.FullName --version 2>&1 | Out-String
} else {
  Write-Host "openscad.exe not found, listing tree:"
  Get-ChildItem $dest -Recurse | Select-Object -First 20 FullName | Out-String
}

